insert into public.obligations (obligation_key, position, role, risk_class, high_risk_route, duty, article, applies_from, applies_if, is_informational, relief_note, note, law_version) values
  ('ai-literacy', 0, 'provider', 'high_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, false, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 1, 'provider', 'limited_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, false, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 2, 'provider', 'minimal_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, false, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 3, 'deployer', 'high_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, false, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 4, 'deployer', 'limited_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, false, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 5, 'deployer', 'minimal_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, false, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('prohibited-practice', 6, 'provider', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1', '2025-02-02', 'The practice falls under Art. 5(1) points (a) to (h).', false, null, null, 'amended'),
  ('prohibited-practice', 7, 'deployer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1', '2025-02-02', 'The practice falls under Art. 5(1) points (a) to (h).', false, null, null, 'amended'),
  ('prohibited-practice', 8, 'importer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1', '2025-02-02', 'The practice falls under Art. 5(1) points (a) to (h).', false, null, null, 'amended'),
  ('prohibited-intimate-imagery', 9, 'provider', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:ba', '2026-12-02', 'The system generates or manipulates realistic intimate or sexually explicit images, video or audio of an identifiable person without their explicit consent (new prohibition added by the Omnibus).', false, null, null, 'amended'),
  ('prohibited-intimate-imagery', 10, 'deployer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:ba', '2026-12-02', 'The system generates or manipulates realistic intimate or sexually explicit images, video or audio of an identifiable person without their explicit consent (new prohibition added by the Omnibus).', false, null, null, 'amended'),
  ('prohibited-intimate-imagery', 11, 'importer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:ba', '2026-12-02', 'The system generates or manipulates realistic intimate or sexually explicit images, video or audio of an identifiable person without their explicit consent (new prohibition added by the Omnibus).', false, null, null, 'amended'),
  ('prohibited-csam', 12, 'provider', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:bb', '2026-12-02', 'The system generates or manipulates child sexual abuse material (new prohibition added by the Omnibus).', false, null, null, 'amended'),
  ('prohibited-csam', 13, 'deployer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:bb', '2026-12-02', 'The system generates or manipulates child sexual abuse material (new prohibition added by the Omnibus).', false, null, null, 'amended'),
  ('prohibited-csam', 14, 'importer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:bb', '2026-12-02', 'The system generates or manipulates child sexual abuse material (new prohibition added by the Omnibus).', false, null, null, 'amended'),
  ('prohibited-distributor', 15, 'distributor', 'prohibited', null, 'This system can''t lawfully be placed on the EU market or used (Art. 5). The Act doesn''t name distributors in Art. 5, but don''t supply it.', 'art:5:1', '2025-02-02', 'The practice falls under Art. 5(1) points (a) to (h).', true, null, null, 'amended'),
  ('prohibited-distributor-intimate-imagery', 16, 'distributor', 'prohibited', null, 'This system can''t lawfully be placed on the EU market or used (Art. 5). The Act doesn''t name distributors in Art. 5, but don''t supply it.', 'art:5:1:ba', '2026-12-02', 'The system generates or manipulates realistic intimate or sexually explicit images, video or audio of an identifiable person without their explicit consent.', true, null, null, 'amended'),
  ('prohibited-distributor-csam', 17, 'distributor', 'prohibited', null, 'This system can''t lawfully be placed on the EU market or used (Art. 5). The Act doesn''t name distributors in Art. 5, but don''t supply it.', 'art:5:1:bb', '2026-12-02', 'The system generates or manipulates child sexual abuse material.', true, null, null, 'amended'),
  ('hr-provider-requirements', 18, 'provider', 'high_risk', 'annex_i', 'Make sure the system meets the high-risk requirements: risk management, data governance, technical documentation, logging, instructions for deployers, human oversight, accuracy, robustness and cybersecurity (Art. 9 to 15).', 'art:16:a', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-requirements', 19, 'provider', 'high_risk', 'annex_iii', 'Make sure the system meets the high-risk requirements: risk management, data governance, technical documentation, logging, instructions for deployers, human oversight, accuracy, robustness and cybersecurity (Art. 9 to 15).', 'art:16:a', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-contact', 20, 'provider', 'high_risk', 'annex_i', 'Put your name, registered trade name or trade mark and contact address on the system, its packaging or its documentation.', 'art:16:b', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-contact', 21, 'provider', 'high_risk', 'annex_iii', 'Put your name, registered trade name or trade mark and contact address on the system, its packaging or its documentation.', 'art:16:b', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-qms', 22, 'provider', 'high_risk', 'annex_i', 'Have a documented quality management system (Art. 17).', 'art:16:c', '2028-08-02', null, false, 'The quality management system may be proportionate to the size of the organisation for SMEs, including start-ups, and SMCs (Art. 17(2)). SMEs without partner or linked enterprises may comply with certain elements in a simplified manner (Art. 63(1)).', null, 'amended'),
  ('hr-provider-qms', 23, 'provider', 'high_risk', 'annex_iii', 'Have a documented quality management system (Art. 17).', 'art:16:c', '2027-12-02', null, false, 'The quality management system may be proportionate to the size of the organisation for SMEs, including start-ups, and SMCs (Art. 17(2)). SMEs without partner or linked enterprises may comply with certain elements in a simplified manner (Art. 63(1)).', null, 'amended'),
  ('hr-provider-technical-documentation', 24, 'provider', 'high_risk', 'annex_i', 'Draw up the technical documentation (Annex IV) before placing the system on the market, and keep it up to date.', 'art:11:1', '2028-08-02', null, false, 'SMEs, including start-ups, and SMCs may provide the Annex IV elements in a simplified manner, using the Commission''s simplified form (Art. 11(1)). As of 24 September 2026 the form did not appear to be published.', null, 'amended'),
  ('hr-provider-technical-documentation', 25, 'provider', 'high_risk', 'annex_iii', 'Draw up the technical documentation (Annex IV) before placing the system on the market, and keep it up to date.', 'art:11:1', '2027-12-02', null, false, 'SMEs, including start-ups, and SMCs may provide the Annex IV elements in a simplified manner, using the Commission''s simplified form (Art. 11(1)). As of 24 September 2026 the form did not appear to be published.', null, 'amended'),
  ('hr-provider-keep-documentation', 26, 'provider', 'high_risk', 'annex_i', 'Keep the technical documentation, quality management documents and declaration of conformity for 10 years (Art. 18).', 'art:16:d', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-keep-documentation', 27, 'provider', 'high_risk', 'annex_iii', 'Keep the technical documentation, quality management documents and declaration of conformity for 10 years (Art. 18).', 'art:16:d', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-logs', 28, 'provider', 'high_risk', 'annex_i', 'Keep the logs the system generates automatically, where they are under your control (Art. 19).', 'art:16:e', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-logs', 29, 'provider', 'high_risk', 'annex_iii', 'Keep the logs the system generates automatically, where they are under your control (Art. 19).', 'art:16:e', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-conformity-assessment', 30, 'provider', 'high_risk', 'annex_i', 'Have the system undergo the relevant conformity assessment (Art. 43) before placing it on the market or putting it into service.', 'art:16:f', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-conformity-assessment', 31, 'provider', 'high_risk', 'annex_iii', 'Have the system undergo the relevant conformity assessment (Art. 43) before placing it on the market or putting it into service.', 'art:16:f', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-declaration', 32, 'provider', 'high_risk', 'annex_i', 'Draw up an EU declaration of conformity (Art. 47).', 'art:16:g', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-declaration', 33, 'provider', 'high_risk', 'annex_iii', 'Draw up an EU declaration of conformity (Art. 47).', 'art:16:g', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-ce-marking', 34, 'provider', 'high_risk', 'annex_i', 'Affix the CE marking to the system, its packaging or its documentation (Art. 48).', 'art:16:h', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-ce-marking', 35, 'provider', 'high_risk', 'annex_iii', 'Affix the CE marking to the system, its packaging or its documentation (Art. 48).', 'art:16:h', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-registration', 36, 'provider', 'high_risk', 'annex_iii', 'Register yourself and the system in the EU database before placing it on the market (Art. 49(1)).', 'art:16:i', '2027-12-02', null, false, null, 'Systems in Annex III point 2 (critical infrastructure) are registered at national level instead (Art. 49(5)).', 'amended'),
  ('hr-provider-corrective-actions', 37, 'provider', 'high_risk', 'annex_i', 'Take corrective action and inform others when the system is not in conformity (Art. 20).', 'art:16:j', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-corrective-actions', 38, 'provider', 'high_risk', 'annex_iii', 'Take corrective action and inform others when the system is not in conformity (Art. 20).', 'art:16:j', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-demonstrate-conformity', 39, 'provider', 'high_risk', 'annex_i', 'Demonstrate the system''s conformity when a national competent authority asks.', 'art:16:k', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-demonstrate-conformity', 40, 'provider', 'high_risk', 'annex_iii', 'Demonstrate the system''s conformity when a national competent authority asks.', 'art:16:k', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-accessibility', 41, 'provider', 'high_risk', 'annex_i', 'Make sure the system meets the accessibility requirements of Directives (EU) 2016/2102 and (EU) 2019/882.', 'art:16:l', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-provider-accessibility', 42, 'provider', 'high_risk', 'annex_iii', 'Make sure the system meets the accessibility requirements of Directives (EU) 2016/2102 and (EU) 2019/882.', 'art:16:l', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-provider-authorised-representative', 43, 'provider', 'high_risk', 'annex_i', 'Appoint an authorised representative established in the Union, by written mandate, before making the system available.', 'art:22:1', '2028-08-02', 'The provider is established outside the Union.', false, null, null, 'amended'),
  ('hr-provider-authorised-representative', 44, 'provider', 'high_risk', 'annex_iii', 'Appoint an authorised representative established in the Union, by written mandate, before making the system available.', 'art:22:1', '2027-12-02', 'The provider is established outside the Union.', false, null, null, 'amended'),
  ('hr-provider-post-market-monitoring', 45, 'provider', 'high_risk', 'annex_i', 'Set up and document a post-market monitoring system based on a monitoring plan.', 'art:72:1', '2028-08-02', null, false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended'),
  ('hr-provider-post-market-monitoring', 46, 'provider', 'high_risk', 'annex_iii', 'Set up and document a post-market monitoring system based on a monitoring plan.', 'art:72:1', '2027-12-02', null, false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended'),
  ('hr-provider-serious-incidents', 47, 'provider', 'high_risk', 'annex_i', 'Report serious incidents to the market surveillance authority: at the latest 15 days after becoming aware, 10 days in case of death, 2 days for a widespread infringement.', 'art:73:1', '2028-08-02', null, false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended'),
  ('hr-provider-serious-incidents', 48, 'provider', 'high_risk', 'annex_iii', 'Report serious incidents to the market surveillance authority: at the latest 15 days after becoming aware, 10 days in case of death, 2 days for a widespread infringement.', 'art:73:1', '2027-12-02', null, false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended'),
  ('hr-deployer-instructions', 49, 'deployer', 'high_risk', 'annex_i', 'Use the system according to the provider''s instructions for use, with appropriate technical and organisational measures.', 'art:26:1', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-deployer-instructions', 50, 'deployer', 'high_risk', 'annex_iii', 'Use the system according to the provider''s instructions for use, with appropriate technical and organisational measures.', 'art:26:1', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-deployer-human-oversight', 51, 'deployer', 'high_risk', 'annex_i', 'Assign human oversight to people with the necessary competence, training, authority and support.', 'art:26:2', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-deployer-human-oversight', 52, 'deployer', 'high_risk', 'annex_iii', 'Assign human oversight to people with the necessary competence, training, authority and support.', 'art:26:2', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-deployer-input-data', 53, 'deployer', 'high_risk', 'annex_i', 'Make sure the input data is relevant and sufficiently representative for the intended purpose.', 'art:26:4', '2028-08-02', 'You control the input data.', false, null, null, 'amended'),
  ('hr-deployer-input-data', 54, 'deployer', 'high_risk', 'annex_iii', 'Make sure the input data is relevant and sufficiently representative for the intended purpose.', 'art:26:4', '2027-12-02', 'You control the input data.', false, null, null, 'amended'),
  ('hr-deployer-monitoring', 55, 'deployer', 'high_risk', 'annex_i', 'Monitor the system''s operation; if it presents a risk, inform the provider or distributor and the market surveillance authority and suspend its use; report serious incidents to the provider first.', 'art:26:5', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-deployer-monitoring', 56, 'deployer', 'high_risk', 'annex_iii', 'Monitor the system''s operation; if it presents a risk, inform the provider or distributor and the market surveillance authority and suspend its use; report serious incidents to the provider first.', 'art:26:5', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-deployer-logs', 57, 'deployer', 'high_risk', 'annex_i', 'Keep the logs the system generates, where they are under your control, for at least six months.', 'art:26:6', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-deployer-logs', 58, 'deployer', 'high_risk', 'annex_iii', 'Keep the logs the system generates, where they are under your control, for at least six months.', 'art:26:6', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-deployer-inform-workers', 59, 'deployer', 'high_risk', 'annex_i', 'Inform workers'' representatives and the affected workers before using the system at the workplace.', 'art:26:7', '2028-08-02', 'You are an employer and use the system at the workplace.', false, null, null, 'amended'),
  ('hr-deployer-inform-workers', 60, 'deployer', 'high_risk', 'annex_iii', 'Inform workers'' representatives and the affected workers before using the system at the workplace.', 'art:26:7', '2027-12-02', 'You are an employer and use the system at the workplace.', false, null, null, 'amended'),
  ('hr-deployer-registration', 61, 'deployer', 'high_risk', 'annex_iii', 'Register the use of the system in the EU database (Art. 49(3)); do not use a system that is not registered.', 'art:26:8', '2027-12-02', 'You are a public authority or a Union institution, body, office or agency.', false, null, null, 'amended'),
  ('hr-deployer-dpia', 62, 'deployer', 'high_risk', 'annex_i', 'Use the provider''s information (Art. 13) for your data protection impact assessment.', 'art:26:9', '2028-08-02', 'A data protection impact assessment is required under Art. 35 GDPR or Art. 27 of Directive (EU) 2016/680.', false, null, null, 'amended'),
  ('hr-deployer-dpia', 63, 'deployer', 'high_risk', 'annex_iii', 'Use the provider''s information (Art. 13) for your data protection impact assessment.', 'art:26:9', '2027-12-02', 'A data protection impact assessment is required under Art. 35 GDPR or Art. 27 of Directive (EU) 2016/680.', false, null, null, 'amended'),
  ('hr-deployer-post-remote-biometric', 64, 'deployer', 'high_risk', 'annex_iii', 'Get prior (or, at the latest within 48 hours, subsequent) authorisation from a judicial or binding administrative authority for each use, limit each use to a specific offence, document every use in the police file and report annually to the authorities.', 'art:26:10', '2027-12-02', 'You use post-remote biometric identification for law enforcement (targeted search of a person suspected or convicted of a criminal offence).', false, null, null, 'amended'),
  ('hr-deployer-inform-persons', 65, 'deployer', 'high_risk', 'annex_iii', 'Inform the people concerned that they are subject to the use of the high-risk system.', 'art:26:11', '2027-12-02', 'The system makes, or helps make, decisions about natural persons.', false, null, null, 'amended'),
  ('hr-deployer-cooperate', 66, 'deployer', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:26:12', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-deployer-cooperate', 67, 'deployer', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:26:12', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-deployer-fria', 68, 'deployer', 'high_risk', 'annex_iii', 'Carry out a fundamental rights impact assessment before first use, and notify the market surveillance authority of the results.', 'art:27:1', '2027-12-02', 'You are a body governed by public law or a private entity providing public services (except for Annex III point 2), or the system is used for creditworthiness or credit scoring, or for risk assessment and pricing in life and health insurance (Annex III points 5(b) and (c)).', false, null, 'The AI Office is to publish a questionnaire template to simplify this assessment (Art. 27(5)).', 'amended'),
  ('hr-deployer-explanation', 69, 'deployer', 'high_risk', 'annex_iii', 'On request, give an affected person clear and meaningful explanations of the role of the system in the decision and the main elements of the decision taken.', 'art:86:1', '2027-12-02', 'Decisions taken on the basis of the system''s output produce legal effects on people or similarly significantly affect them (not for Annex III point 2, critical infrastructure).', false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended'),
  ('hr-importer-verify', 70, 'importer', 'high_risk', 'annex_i', 'Before placing the system on the market, verify that the provider carried out the conformity assessment, drew up the technical documentation, affixed the CE marking with the declaration of conformity and instructions, and appointed an authorised representative.', 'art:23:1', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-importer-verify', 71, 'importer', 'high_risk', 'annex_iii', 'Before placing the system on the market, verify that the provider carried out the conformity assessment, drew up the technical documentation, affixed the CE marking with the declaration of conformity and instructions, and appointed an authorised representative.', 'art:23:1', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-importer-nonconformity', 72, 'importer', 'high_risk', 'annex_i', 'Do not place a non-conforming or falsified system on the market; if it presents a risk, inform the provider, the authorised representative and the authorities.', 'art:23:2', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-importer-nonconformity', 73, 'importer', 'high_risk', 'annex_iii', 'Do not place a non-conforming or falsified system on the market; if it presents a risk, inform the provider, the authorised representative and the authorities.', 'art:23:2', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-importer-contact', 74, 'importer', 'high_risk', 'annex_i', 'Put your name, registered trade name or trade mark and contact address on the system and its packaging or documentation.', 'art:23:3', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-importer-contact', 75, 'importer', 'high_risk', 'annex_iii', 'Put your name, registered trade name or trade mark and contact address on the system and its packaging or documentation.', 'art:23:3', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-importer-storage', 76, 'importer', 'high_risk', 'annex_i', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:23:4', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-importer-storage', 77, 'importer', 'high_risk', 'annex_iii', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:23:4', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-importer-keep-documents', 78, 'importer', 'high_risk', 'annex_i', 'Keep the notified body''s certificate (if any), the instructions for use and the declaration of conformity for 10 years.', 'art:23:5', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-importer-keep-documents', 79, 'importer', 'high_risk', 'annex_iii', 'Keep the notified body''s certificate (if any), the instructions for use and the declaration of conformity for 10 years.', 'art:23:5', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-importer-provide-information', 80, 'importer', 'high_risk', 'annex_i', 'Give the competent authorities the information and documentation they ask for to demonstrate conformity.', 'art:23:6', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-importer-provide-information', 81, 'importer', 'high_risk', 'annex_iii', 'Give the competent authorities the information and documentation they ask for to demonstrate conformity.', 'art:23:6', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-importer-cooperate', 82, 'importer', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:23:7', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-importer-cooperate', 83, 'importer', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:23:7', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-distributor-verify', 84, 'distributor', 'high_risk', 'annex_i', 'Before making the system available, verify the CE marking, the declaration of conformity and instructions for use, and that the provider and importer put their names and contact details on it.', 'art:24:1', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-distributor-verify', 85, 'distributor', 'high_risk', 'annex_iii', 'Before making the system available, verify the CE marking, the declaration of conformity and instructions for use, and that the provider and importer put their names and contact details on it.', 'art:24:1', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-distributor-nonconformity', 86, 'distributor', 'high_risk', 'annex_i', 'Do not make a non-conforming system available; if it presents a risk, inform the provider or importer.', 'art:24:2', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-distributor-nonconformity', 87, 'distributor', 'high_risk', 'annex_iii', 'Do not make a non-conforming system available; if it presents a risk, inform the provider or importer.', 'art:24:2', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-distributor-storage', 88, 'distributor', 'high_risk', 'annex_i', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:24:3', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-distributor-storage', 89, 'distributor', 'high_risk', 'annex_iii', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:24:3', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-distributor-corrective-actions', 90, 'distributor', 'high_risk', 'annex_i', 'For a non-conforming system you made available, take corrective action, withdraw or recall it, or make sure the provider or importer does.', 'art:24:4', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-distributor-corrective-actions', 91, 'distributor', 'high_risk', 'annex_iii', 'For a non-conforming system you made available, take corrective action, withdraw or recall it, or make sure the provider or importer does.', 'art:24:4', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-distributor-provide-information', 92, 'distributor', 'high_risk', 'annex_i', 'Give the competent authorities the information and documentation they ask for about your actions.', 'art:24:5', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-distributor-provide-information', 93, 'distributor', 'high_risk', 'annex_iii', 'Give the competent authorities the information and documentation they ask for about your actions.', 'art:24:5', '2027-12-02', null, false, null, null, 'amended'),
  ('hr-distributor-cooperate', 94, 'distributor', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:24:6', '2028-08-02', null, false, null, null, 'amended'),
  ('hr-distributor-cooperate', 95, 'distributor', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:24:6', '2027-12-02', null, false, null, null, 'amended'),
  ('transparency-interaction', 96, 'provider', 'limited_risk', null, 'Design the system so that people are informed they are interacting with an AI system, unless that is obvious.', 'art:50:1', '2026-08-02', 'The system is intended to interact directly with natural persons.', false, null, null, 'amended'),
  ('transparency-interaction', 97, 'provider', 'high_risk', null, 'Design the system so that people are informed they are interacting with an AI system, unless that is obvious.', 'art:50:1', '2026-08-02', 'The system is intended to interact directly with natural persons.', false, null, null, 'amended'),
  ('transparency-marking', 98, 'provider', 'limited_risk', null, 'Mark the system''s outputs in a machine-readable format so they are detectable as artificially generated or manipulated.', 'art:50:2', '2026-08-02', 'The system generates synthetic audio, image, video or text content.', false, null, 'Systems placed on the market before 2 August 2026 have until 2 December 2026 to comply (Art. 111(4), added by the Omnibus).', 'amended'),
  ('transparency-marking', 99, 'provider', 'high_risk', null, 'Mark the system''s outputs in a machine-readable format so they are detectable as artificially generated or manipulated.', 'art:50:2', '2026-08-02', 'The system generates synthetic audio, image, video or text content.', false, null, 'Systems placed on the market before 2 August 2026 have until 2 December 2026 to comply (Art. 111(4), added by the Omnibus).', 'amended'),
  ('transparency-emotion-biometric', 100, 'deployer', 'limited_risk', null, 'Inform the people exposed to the system that it is operating, and process their personal data under the GDPR.', 'art:50:3', '2026-08-02', 'The system is an emotion recognition or biometric categorisation system.', false, null, null, 'amended'),
  ('transparency-emotion-biometric', 101, 'deployer', 'high_risk', null, 'Inform the people exposed to the system that it is operating, and process their personal data under the GDPR.', 'art:50:3', '2026-08-02', 'The system is an emotion recognition or biometric categorisation system.', false, null, null, 'amended'),
  ('transparency-deep-fake', 102, 'deployer', 'limited_risk', null, 'Disclose that deep-fake image, audio or video content, or text published to inform the public on matters of public interest, has been artificially generated or manipulated.', 'art:50:4', '2026-08-02', 'The system generates or manipulates deep fakes, or text published to inform the public on matters of public interest (not needed for text under human editorial control).', false, null, null, 'amended'),
  ('transparency-deep-fake', 103, 'deployer', 'high_risk', null, 'Disclose that deep-fake image, audio or video content, or text published to inform the public on matters of public interest, has been artificially generated or manipulated.', 'art:50:4', '2026-08-02', 'The system generates or manipulates deep fakes, or text published to inform the public on matters of public interest (not needed for text under human editorial control).', false, null, null, 'amended'),
  ('annex-iii-exemption', 104, 'provider', 'limited_risk', null, 'Document the assessment before placing the system on the market, register it in the EU database (Art. 49(2)), and hand the assessment to national authorities on request.', 'art:6:4', '2027-12-02', 'The system is listed in Annex III, but you concluded under Art. 6(3) that it is not high-risk.', false, null, 'The Omnibus kept this registration but simplified its content (Omnibus recital 22). The date follows Art. 113(c)(i), but that covers systems "classified as high-risk"; a literal reading (and Art. 49 being in Chapter VIII) gives 2 August 2026. Check with a lawyer.', 'amended'),
  ('annex-iii-exemption', 105, 'provider', 'minimal_risk', null, 'Document the assessment before placing the system on the market, register it in the EU database (Art. 49(2)), and hand the assessment to national authorities on request.', 'art:6:4', '2027-12-02', 'The system is listed in Annex III, but you concluded under Art. 6(3) that it is not high-risk.', false, null, 'The Omnibus kept this registration but simplified its content (Omnibus recital 22). The date follows Art. 113(c)(i), but that covers systems "classified as high-risk"; a literal reading (and Art. 49 being in Chapter VIII) gives 2 August 2026. Check with a lawyer.', 'amended');
